async def main():
    current = all_sources()
    existing_names = {re.sub(r"[^a-z0-9]", "", s["company"].lower()) for s in current}
    existing_boards = {(s["ats"], s.get("slug")) for s in current}
    found, attempted = [], set()
    semaphore = asyncio.Semaphore(12)
    async with make_client() as client:
        async def inspect(name, sector):
            slug = re.sub(r"[^a-z0-9-]", "", name.lower())
            if re.sub(r"[^a-z0-9]", "", name.lower()) in existing_names or slug in attempted:
                return
            attempted.add(slug)
            async with semaphore:
                for ats, url in [("greenhouse", f"https://boards-api.greenhouse.io/v1/boards/{slug}/jobs"), ("lever", f"https://api.lever.co/v0/postings/{slug}?mode=json"), ("ashby", f"https://api.ashbyhq.com/posting-api/job-board/{slug}")]:
                    if (ats, slug) in existing_boards:
                        continue
                    try:
                        response = await asyncio.wait_for(client.get(url), timeout=15)
                        if response.status_code != 200:
                            continue
                        data = response.json()
                        jobs = data if ats == "lever" else data.get("jobs", [])
                        if not jobs:
                            continue
                        item = {"source": {"company": name, "ats": ats, "slug": slug}, "sector": sector, "count": len(jobs), "titles": [j.get("text", j.get("title")) for j in jobs[:3]]}
                        if ats == "greenhouse":
                            board = await client.get(f"https://boards-api.greenhouse.io/v1/boards/{slug}")
                            item["board_name"] = board.json().get("name")
                        found.append(item)
                        Path("bio_100_discovery.json").write_text(json.dumps(found, indent=2), encoding="utf-8")
                        print(json.dumps(item), flush=True)
                    except Exception:
                        pass
        await asyncio.gather(*(inspect(name, sector) for sector, names in GROUPS.items() for name in names))
    print("Candidate boards:", len(found), "unique candidate slugs:", len(attempted))

if __name__ == "__main__":
    asyncio.run(main())
